<?php $settingsData = $settingsData ?? []; $on = static fn(string $key): bool => ($settingsData[$key] ?? true) !== false; ?>
<section class="mx-auto max-w-7xl"><header class="cms-header slide-in"><div><p class="eyebrow">Admin CMS</p><h1 class="section-title mt-3">Comment Settings</h1><p class="mt-4 max-w-2xl text-base leading-7 text-neutral-600">Atur perilaku komentar publik secara global.</p></div></header><section class="admin-card mt-6 p-4 md:p-6"><form id="comment-setting-form" class="grid gap-4 md:grid-cols-2" data-ssr="true"><label class="grid gap-2 text-sm font-semibold text-neutral-700"><span>Comments Enabled</span><select name="comments.enabled" class="config-input js-admin-custom-select"><option value="1" <?= $on('comments.enabled') ? 'selected' : '' ?>>On</option><option value="0" <?= !$on('comments.enabled') ? 'selected' : '' ?>>Off</option></select></label><label class="grid gap-2 text-sm font-semibold text-neutral-700"><span>Voting Enabled</span><select name="comments.voting_enabled" class="config-input js-admin-custom-select"><option value="1" <?= $on('comments.voting_enabled') ? 'selected' : '' ?>>On</option><option value="0" <?= !$on('comments.voting_enabled') ? 'selected' : '' ?>>Off</option></select></label><label class="grid gap-2 text-sm font-semibold text-neutral-700"><span>Replies Enabled</span><select name="comments.replies_enabled" class="config-input js-admin-custom-select"><option value="1" <?= $on('comments.replies_enabled') ? 'selected' : '' ?>>On</option><option value="0" <?= !$on('comments.replies_enabled') ? 'selected' : '' ?>>Off</option></select></label><label class="grid gap-2 text-sm font-semibold text-neutral-700"><span>Replies Require Moderation</span><select name="comments.replies_require_moderation" class="config-input js-admin-custom-select"><option value="1" <?= $on('comments.replies_require_moderation') ? 'selected' : '' ?>>On</option><option value="0" <?= !$on('comments.replies_require_moderation') ? 'selected' : '' ?>>Off</option></select></label><label class="grid gap-2 text-sm font-semibold text-neutral-700"><span>Max Reply Depth</span><input name="comments.max_reply_depth" type="number" min="1" max="10" class="config-input" value="<?= (int) ($settingsData['comments.max_reply_depth'] ?? 3) ?>"></label><label class="grid gap-2 text-sm font-semibold text-neutral-700"><span>Root Sort</span><select name="comments.root_sort" class="config-input js-admin-custom-select"><?php foreach (['newest_first' => 'Newest First', 'oldest_first' => 'Oldest First', 'top_voted' => 'Top Voted'] as $key => $label): ?><option value="<?= $key ?>" <?= ($settingsData['comments.root_sort'] ?? '') === $key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label><label class="grid gap-2 text-sm font-semibold text-neutral-700"><span>Reply Sort</span><select name="comments.reply_sort" class="config-input js-admin-custom-select"><?php foreach (['oldest_first' => 'Oldest First', 'newest_first' => 'Newest First', 'top_voted' => 'Top Voted'] as $key => $label): ?><option value="<?= $key ?>" <?= ($settingsData['comments.reply_sort'] ?? '') === $key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label><label class="grid gap-2 text-sm font-semibold text-neutral-700"><span>Comment Rate Limit / 15 min</span><input name="comments.rate_limit_per_ip_per_15min" type="number" min="1" max="500" class="config-input" value="<?= (int) ($settingsData['comments.rate_limit_per_ip_per_15min'] ?? 20) ?>"></label><label class="grid gap-2 text-sm font-semibold text-neutral-700"><span>Vote Rate Limit / 15 min</span><input name="comments.vote_rate_limit_per_ip_per_15min" type="number" min="1" max="500" class="config-input" value="<?= (int) ($settingsData['comments.vote_rate_limit_per_ip_per_15min'] ?? 60) ?>"></label><div class="md:col-span-2"><button type="submit" class="btn btn-primary">Simpan Pengaturan</button></div></form></section></section>
